def min_digit(n):
    return min(int(d) for d in str(n))

def max_digit(n):
    return max(int(d) for d in str(n))

def compute_sequence(a1, k):
    current = a1
    for _ in range(k - 1):
        current += min_digit(current) * max_digit(current)
    return current

t = int(input())
for _ in range(t):
    a1, k = map(int, input().split())
    print(compute_sequence(a1, k))
"}

