import sys

t = int(sys.stdin.readline())

test_cases = []
for _ in range(t):
    a, b = map(int, sys.stdin.readline().split())
    test_cases.append((a, b))

# Process each test case
for a, b in test_cases:
    if a == b:
        print(0)
    else:
        # Find minimum k such that either a + S_k == b or b + S_k == a
        # and we can distribute operations appropriately
        found = False
        for k in range(1, 10000):
            s_k = k * (k + 1) // 2
            if a > b:
                # We need to add to a: a + sum_added_to_a = b + (s_k - sum_added_to_a)
                # => 2 * sum_added_to_a = b - a + s_k
                # => sum_added_to_a = (b - a + s_k) / 2
                # Must be even and >= 0
                if (b - a + s_k) % 2 == 0:
                    found = True
                    break
            else:
                # Similarly, if b > a
                if (a - b + s_k) % 2 == 0:
                    found = True
                    break
        print(k)
