def normalize(login):
    normalized = ""
    for c in login:
        lower_c = c.lower()
        if lower_c == 'o':
            normalized += '0'
        elif lower_c == 'l' or lower_c == 'i':
            normalized += 'l'
        elif lower_c == '1':
            normalized += 'l'
        else:
            normalized += lower_c
    return normalized

# Read input
s = input().strip()
n = int(input())
existing = [input().strip() for _ in range(n)]

# Normalize
normalized_s = normalize(s)
normalized_existing = [normalize(login) for login in existing]

# Check if any existing login matches
if normalized_s in normalized_existing:
    print("No")
else:
    print("Yes")
