import math

def count_good_pairs(l, r, x, y):
    if y % x != 0:
        return 0

    k = y // x

    def gcd(a, b):
        return math.gcd(a, b)

    def get_divisors(n):
        divisors = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return sorted(divisors)

    divisors = get_divisors(k)
    count = 0

    for i in divisors:
        j = k // i
        if gcd(i, j) == 1:
            a = x * i
            b = x * j
            if l <= a <= r and l <= b <= r:
                if a != b:
                    count += 2
                else:
                    count += 1

    return count

# Read input
l, r, x, y = map(int, input().split())

# Solve and print
print(count_good_pairs(l, r, x, y))
"}

