import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Dictionary to store students per subject
    subjects = {}

    for _ in range(n):
        s = int(next(it))
        r = int(next(it))
        if s not in subjects:
            subjects[s] = []
        subjects[s].append(r)

    # For each subject, sort by skill descending and compute prefix sums
    prefix_sums = {}
    max_students = 0
    for s in subjects:
        students = subjects[s]
        students.sort(reverse=True)
        prefix = [0]
        for r in students:
            prefix.append(prefix[-1] + r)
        prefix_sums[s] = prefix
        max_students = max(max_students, len(students))

    # Try each possible k (number of students per chosen subject)
    best = 0
    for k in range(1, max_students + 1):
        # Get possible subjects and their sum for taking k students
        available = {}
        for s in subjects:
            if len(subjects[s]) >= k:
                available[s] = prefix_sums[s][k]

        # Dynamic programming: dp[i] = maximum total sum using first i subjects
        # We can either take the i-th subject or not
        dp = [0] * (len(available) + 1)
        for idx, (s, val) in enumerate(available.items(), 1):
            dp[idx] = max(dp[idx-1] + val, dp[idx-1])

        best = max(best, dp[-1])

    print(best if best > 0 else 0)

if __name__ == "__main__":
    solve()
"}

