x_coords = set()
y_coords = set()

vertical_segments = []
horizontal_segments = []

for _ in range(4):
    x1, y1, x2, y2 = map(int, input().split())

    # Check if segment is vertical
    if x1 == x2:
        vertical_segments.append((x1, y1, x2, y2))
    # Check if segment is horizontal
    elif y1 == y2:
        horizontal_segments.append((x1, y1, x2, y2))

    # Add endpoints to coordinate sets
    x_coords.add(x1)
    x_coords.add(x2)
    y_coords.add(y1)
    y_coords.add(y2)

# Check if we have exactly 2 distinct x and y coordinates
if len(x_coords) != 2 or len(y_coords) != 2:
    print("NO")
else:
    # Check if we have exactly 2 vertical and 2 horizontal segments
    if len(vertical_segments) != 2 or len(horizontal_segments) != 2:
        print("NO")
    else:
        # Extract left/right x and bottom/top y
        x_values = sorted(x_coords)
        y_values = sorted(y_coords)
        left_x, right_x = x_values
        bottom_y, top_y = y_values

        # Check if vertical segments are the left and right sides
        # A vertical segment should span from bottom to top
        left_vertical = None
        right_vertical = None

        for seg in vertical_segments:
            if seg[1] == bottom_y and seg[3] == top_y:
                if seg[0] == left_x:
                    left_vertical = seg
                else:
                    right_vertical = seg

        # Check if horizontal segments are the bottom and top sides
        # A horizontal segment should span from left to right
        bottom_horizontal = None
        top_horizontal = None

        for seg in horizontal_segments:
            if seg[1] == bottom_y and seg[3] == right_x:
                if seg[0] == left_x:
                    bottom_horizontal = seg
                else:
                    top_horizontal = seg
            elif seg[1] == top_y and seg[3] == right_x:
                if seg[0] == left_x:
                    bottom_horizontal = seg
                else:
                    top_horizontal = seg

        # Check if we found all four sides
        if left_vertical and right_vertical and bottom_horizontal and top_horizontal:
            print("YES")
        else:
            print("NO")
