import sys

def can_gather_all_disks(n, a):
    # We need to check if we can move all disks to the last position

    # Create a copy of the array
    arr = a[:]

    # We'll use a greedy approach: move smaller disks to the right
    # First, bubble smaller disks to the right
    for i in range(n - 2, -1, -1):
        # Move from i to i+1 if possible
        if arr[i] < arr[i + 1] or arr[i + 1] == 0:
            # Move the smaller disk to the right
            if arr[i] < arr[i + 1]:
                arr[i + 1] = arr[i]
                arr[i] = 0
            # If arr[i+1] == 0, we just need to know we can move

    # Now check if all non-zero disks are at the end
    return all(x == 0 for x in arr[1:-1])

