                for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.':
                        seen.add(component_id[nx][ny])

                # If the '*' cell is at a corner, it might connect components
                # through neighboring cells that are not directly adjacent
                # We need to consider components that are connected through this cell

                # Create adjacency list for components
                adj = [[] for _ in range(current_id)]

                # Find which components are adjacent to each other through this '*'
                for comp_id in seen:
                    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nx, ny = i + dx, j + dy
                        if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.':
