MOD = 10**9 + 7

def ncr(n, r, mod):
    """n choose r modulo mod"""
    if r > n or r < 0:
        return 0
    if r == 0:
        return 1
    if r == n:
        return 1
    if r > n - r:
        r = n - r
    res = 1
    for i in range(r):
        res = res * (n - i) % mod
        res = res * pow(i + 1, mod - 2, mod) % mod
    return res

def solve():
    n, l, r = map(int, input().split())

    # Count numbers between l and r for each remainder modulo 3
    # Using arithmetic sequence formula: a, a+d, ..., last
    # cnt = ((last - a) // d) + 1

    # cnt0 = numbers ≡ 0 mod 3
    a0 = (l + (l % 3 != 0))  # smallest number >= l that is ≡ 0 mod 3
    if l % 3 == 0:
        a0 = l
    else:
        a0 = l + (3 - (l % 3))
    last0 = r - (r % 3)
    if last0 < a0:
        cnt0 = 0
    else:
        cnt0 = ((last0 - a0) // 3) + 1

    # cnt1 = numbers ≡ 1 mod 3
    a1 = (l + (l % 3 != 1))
    if l % 3 == 1:
        a1 = l
    else:
        a1 = l + (3 - (l % 3 + 1)) % 3
    last1 = r - (r % 3 + 1)
    if last1 < a1:
        cnt1 = 0
    else:
        cnt1 = ((last1 - a1) // 3) + 1

    # cnt2 = numbers ≡ 2 mod 3
    a2 = (l + (l % 3 != 2))
    if l % 3 == 2:
        a2 = l
    else:
        a2 = l + (3 - (l % 3 + 2)) % 3
    last2 = r - (r % 3 + 2)
    if last2 < a2:
        cnt2 = 0
    else:
        cnt2 = ((last2 - a2) // 3) + 1

    ans = (ncr(cnt0, n, MOD) + ncr(cnt1, n, MOD) + ncr(cnt2, n, MOD)) % MOD

    ans = (ans + ncr(cnt0, n - 1, MOD) * ((cnt1 + cnt2) % MOD) % MOD) % MOD
    ans = (ans + ncr(cnt0, n - 2, MOD) * (cnt1 % MOD) * (cnt2 % MOD) % MOD) % MOD

    print(ans)

solve()
