def solve():
    import sys
    input = sys.stdin.buffer.read().splitlines()

    if not input:
        return

    data = input[0].split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = []

    for i in range(1, n + 1):
        grid.append(input[i].decode().rstrip('\r\n'))

    # Find all connected components of empty cells
    visited = [False] * (n * m)
    components = []

    # BFS to find components
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i * m + j]:
                # Start BFS
                queue = [(i, j)]
                visited[i * m + j] = True
                component = [(i, j)]

                while queue:
                    x, y = queue.pop(0)

                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            idx = nx * m + ny
                            if grid[nx][ny] == '.' and not visited[idx]:
                                visited[idx] = True
                                queue.append((nx, ny))
                                component.append((nx, ny))

                components.append(component)

    # Build mapping from (x, y) to component index
    component_map = [-1] * (n * m)
    for idx, component in enumerate(components):
        for x, y in component:
            component_map[x * m + y] = idx

    # Also store component sizes
    component_size = [len(c) for c in components]

    # Build result
    result = [''] * n
    for i in range(n):
        for j in range(m):
            idx = i * m + j
            if grid[i][j] == '.':
                result[i] += '.'
            else:
                # This is an '*' cell, find the component it would join
                # If we imagine this cell is '.', we need to find which component it connects to

                # Find all adjacent empty cells and their component indices
                adj_components = set()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        idx2 = nx * m + ny
                        if grid[nx][ny] == '.':
                            component_idx = component_map[idx2]
                            adj_components.add(component_idx)

                # The size is 1 (for the new cell) plus the sum of adjacent components
                total_size = 1
                for idx2 in adj_components:
                    total_size += component_size[idx2]

                result[i] += str(total_size % 10)

    sys.stdout.write("\n".join(result))

if __name__ == "__main__":
    solve()
