def lcs(X, Y):
    m = len(X)
    n = len(Y)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if X[i-1] == Y[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[m][n]

def solve():
    n, m = map(int, input().split())
    A = input().strip()
    B = input().strip()

    max_score = 0

    # Try all possible substrings for A
    for i in range(n):
        for j in range(i, n):
            # A[i..j] is a substring of A
            for k in range(m):
                for l in range(k, m):
                    # B[k..l] is a substring of B
                    # Calculate LCS of A[i..j] and B[k..l]
                    c = A[i:j+1]
                    d = B[k:l+1]
                    lcs_val = lcs(c, d)
                    score = 4 * lcs_val - len(c) - len(d)
                    if score > max_score:
