def find_min_jumps(x):
    """Find the minimum number of jumps to reach position x."""
    # Let's trace through all possibilities recursively
    # For n jumps, we can be at position y after n-1 jumps, then either
    # y + n (if we do the +n jump) or y - 1 (if we do the -1 jump)

    # We need to find the smallest n such that x can be reached
    def can_reach(x, n):
        # Base case: after 1 jump
        if n == 1:
            return x == 1 or x == -1

        # Try all positions reachable with n-1 jumps
        for prev_pos in positions_reachable(n-1):
            # First jump: +n
            if can_reach(prev_pos + n, n-1):
                return True
            # Second jump: -1
            if can_reach(prev_pos - 1, n-1):
                return True
        return False

    def positions_reachable(n):
        # This would recursively build all reachable positions
        # But this is too complex for large n...
        return []

    n = 1
    while True:
        if can_reach(x, n):
            return n
        n += 1

# Read input and output results
t = int(input())
for _ in range(t):
    x = int(input())
    print(find_min_jumps(x))
