def are_neighbors(c1, c2):
    return c1 == c2 or (c1 == 'a' and c2 == 'b') or (c1 == 'b' and c2 == 'a') or (c1 == 'b' and c2 == 'c') or (c1 == 'c' and c2 == 'b')

def is_valid_assignment(n, edges, assignment):
    # Check if assignment is valid for the given graph
    # assignment: list of characters for each vertex
    # edges: list of tuples (u, v)

    # Check all edges
    for u, v in edges:
        c1 = assignment[u - 1]
        c2 = assignment[v - 1]
        if not are_neighbors(c1, c2):
            return False

    # Check all non-edges
    for i in range(n):
        for j in range(n):
            if i != j and (i, j) not in edges and (j, i) not in edges:
                c1 = assignment[i]
                c2 = assignment[j]
                if c1 == c2 or (c1 == 'a' and c2 == 'c') or (c1 == 'c' and c2 == 'a'):
                    return False

    return True

# Try all possible assignments (brute force)
def solve(n, edges):
    # Try all possible character assignments
    for assignment in product(['a', 'b', 'c'], repeat=n):
        if is_valid_assignment(n, edges, assignment):
            return assignment

    return None

import sys
from itertools import product

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    edges = []
    for _ in range(m):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        edges.append((u, v))

    assignment = solve(n, edges)

    if assignment:
        print("Yes")
        print(''.join(assignment))
    else:
        print("No")

if __name__ == "__main__":
    main()
