    normalized = []
    for c in login:
        if c in 'Oo0':
            normalized.append('o')
        elif c in '1lI':
            normalized.append('i')
        else:
            normalized.append(c.lower())
    return ''.join(normalized)

new_normalized = normalize(s)

for existing_login in existing:
    if normalize(existing_login) == new_normalized:
        print("No")
        exit()

print("Yes")
