def get_suffix(line: str, k: int) -> str:
    """Get the suffix starting from the k-th vowel from the end."""
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Find all vowels in reverse order
    vowels_indices = []
    for i, char in enumerate(reversed(line)):
        if char in vowels:
            vowels_indices.append(len(line) - i)

    # Check if there are at least k vowels
    if len(vowels_indices) < k:
        return None

    # Get the start index of the k-th vowel from the end
    start_index = vowels_indices[-k]

    # Return the suffix from start_index to end
    return line[start_index:]

def get_rhyme_scheme(quatrain: list[str], k: int) -> str:
    """Determine the rhyme scheme of a quatrain."""
    suffixes = [get_suffix(line, k) for line in quatrain]

    # Check if all lines rhyme
    if all(s == suffixes[0] for s in suffixes):
        return "aaaa"

    # Check for aabb
    if suffixes[0] == suffixes[1] and suffixes[2] == suffixes[3]:
        return "aabb"

    # Check for abab
    if suffixes[0] == suffixes[2] and suffixes[1] == suffixes[3]:
        return "abab"

    # Check for abba
    if suffixes[0] == suffixes[3] and suffixes[1] == suffixes[2]:
        return "abba"

    return "NO"

def solve():
    """Solve the problem."""
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    lines = data[2:2+4*n]

    # Process each quatrain
    quatrains = []
    for i in range(0, 4*n, 4):
        quatrain = lines[i:i+4]
        quatrains.append(quatrain)

    # Determine the rhyme scheme for each quatrain
    schemes = [get_rhyme_scheme(quatrain, k) for quatrain in quatrains]

    # Find the common scheme
    common_scheme = None
    for scheme in schemes:
        if scheme == "NO":
            common_scheme = "NO"
            break
        if common_scheme is None:
            common_scheme = scheme
        elif scheme != common_scheme:
            common_scheme = "NO"
            break

    print(common_scheme)

if __name__ == "__main__":
    solve()
"}

