import sys
import threading

def has_cycle(n, adj):
    """Check if a directed graph has a cycle using DFS"""
    visited = [False] * (n + 1)
    recursion_stack = [False] * (n + 1)

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            recursion_stack[node] = True

            for neighbor in adj[node]:
                if not visited[neighbor]:
                    if dfs(neighbor):
                        return True
                elif recursion_stack[neighbor]:
                    return True

            recursion_stack[node] = False
            return False

    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i):
                return True
    return False

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        # Build adjacency list for directed edges
        adj = [[] for _ in range(n + 1)]
        undirected_edges = []

        for _ in range(m):
            t_i = int(next(it))
            x = int(next(it))
            y = int(next(it))

            if t_i == 1:
                # Directed edge x -> y
                adj[x].append(y)
            else:
                # Undirected edge, store for later
                undirected_edges.append((x, y))

        # Check if directed edges alone form a cycle
        if has_cycle(n, adj):
            print("NO")
        else:
            print("YES")

            # Add directed edges
            for i in range(1, n + 1):
                for neighbor in adj[i]:
                    print(i, neighbor)

            # Add undirected edges arbitrarily (from smaller to larger)
            for x, y in undirected_edges:
                if x < y:
                    print(x, y)
                else:
                    print(y, x)

threading.Thread(target=solve).start()
