def has_cycle(n, adj, visited, recursion_stack, vertex):
    visited[vertex] = True
    recursion_stack[vertex] = True

    for neighbor in adj[vertex]:
        if not visited[neighbor]:
            if has_cycle(n, adj, visited, recursion_stack, neighbor):
                return True
        elif recursion_stack[neighbor]:
            return True

    recursion_stack[vertex] = False
    return False

def topological_sort(n, adj):
    visited = [False] * (n + 1)
    order = []

    def dfs(v):
        visited[v] = True
        for u in adj[v]:
            if not visited[u]:
                dfs(u)
        order.append(v)

    for v in range(1, n + 1):
        if not visited[v]:
            dfs(v)

    return order[::-1]  # Reverse for topological order

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    t = int(data[idx]); idx += 1

    for _ in range(t):
        n = int(data[idx]); idx += 1
        m = int(data[idx]); idx += 1

        adj = [[] for _ in range(n + 1)]
        directed_edges = []

        for _ in range(m):
            t_i = int(data[idx]); idx += 1
            x = int(data[idx]); idx += 1
            y = int(data[idx]); idx += 1

            if t_i == 1:
                # Directed edge
                adj[x].append(y)
                directed_edges.append((x, y))
            else:
                # Undirected edge, store for later
                directed_edges.append((x, y, 'undirected'))

        # Check for cycle in directed edges
        visited = [False] * (n + 1)
        recursion_stack = [False] * (n + 1)
        has_cycle_flag = False

        for vertex in range(1, n + 1):
            if not visited[vertex]:
                if has_cycle(n, adj, visited, recursion_stack, vertex):
                    has_cycle_flag = True
                    break

        if has_cycle_flag:
            print("NO")
            continue

        # Perform topological sort on the directed part of the graph
        order = topological_sort(n, adj)

        # Direct undirected edges based on topological order
        output = []
        for edge in directed_edges:
            if edge[2] == 'undirected':
                x, y, _ = edge
                # Get positions in topological order
                pos_x = order.index(x)
                pos_y = order.index(y)

                # Direct from lower to higher in topological order
                if pos_x < pos_y:
                    output.append((x, y))
                else:
                    output.append((y, x))
            else:
                output.append(edge[:2])

        print("YES")
        for edge in output:
            print(edge[0], edge[1])

