import sys

def min_digit(x):
    return min(int(d) for d in str(x))

def max_digit(x):
    return max(int(d) for d in str(x))

def solve() -> None:
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    idx = 1

    for _ in range(t):
        a1 = int(data[idx])
        K = int(data[idx + 1])
        idx += 2

        if K == 1:
            print(a1)
            continue

        current = a1
        seen = {current: 0}  # value: step

        for step in range(1, K + 1):
            if current in seen:
                # Found a repeat, we're in a cycle
                cycle_start_step = seen[current]
                cycle_length = step - cycle_start_step

                # We need to find a_K
                if cycle_start_step >= K:
                    # Already in cycle from start
                    print(current)
                    break
                else:
                    # Stay in cycle
                    remaining = K - cycle_start_step
                    pos_in_cycle = remaining % cycle_length
                    print(current + (current - seen[current]) * pos_in_cycle // cycle_length)
                    break

            min_d = min_digit(current)
            max_d = max_digit(current)
            current += min_d * max_d

            if min_d == 0 or max_d == 0:
                # Addition will be 0 from now on
                if step >= K:
                    print(current)
                    break
                else:
                    print(current)
                    break

        else:
            # No repeat found in K steps
            print(current)

if __name__ == "__main__":
    solve()
