    data = sys.stdin.read().strip().split()
    t = int(data[0])
    idx = 1

    for _ in range(t):
        a1 = int(data[idx])
        K = int(data[idx + 1])
        idx += 2

        if K == 1:
            print(a1)
            continue

        current = a1
        seen = {current: 0}  # value: step (0-based step count)

        for step in range(1, K):  # iterate K-1 times
            if current in seen:
                # Found a repeat, we're in a cycle
                cycle_start_step = seen[current]
                cycle_length = step - cycle_start_step

                # We need to find a_K
                if cycle_start_step >= K:
                    # Already in cycle from start
                    print(current)
                    break
                else:
                    # Stay in cycle
                    remaining = K - cycle_start_step
                    pos_in_cycle = remaining % cycle_length
                    print(current + (current - seen[current]) * pos_in_cycle // cycle_length)
                    break

            min_d = min_digit(current)
            max_d = max_digit(current)
            current += min_d * max_d

            if min_d == 0 or max_d == 0:
                # Addition will be 0 from now on
                if step >= K:
                    print(current)
                    break
                else:
                    print(current)
                    break

        else:
            # No repeat found in K-1 steps, so current is a_K
            print(current)

