def get_suffix(line, k):
    """Get the suffix starting from the k-th vowel from the end"""
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Find the positions of vowels
    vowel_positions = []
    for i, c in enumerate(line):
        if c in vowels:
            vowel_positions.append(i)

    # If not enough vowels, return None
    if len(vowel_positions) < k:
        return None

    # Get the k-th vowel from the end
    start_pos = vowel_positions[-k]
    return line[start_pos:]  # Return the suffix from that position

def get_rhyme_group(lines, k):
    """Get a tuple representing which lines rhyme in a quatrain"""
    suffixes = []
    for line in lines:
        suffix = get_suffix(line, k)
        if suffix is None:
            return None  # This line cannot rhyme with any other
        suffixes.append(suffix)

    # Group by suffix
    rhyme_groups = []
    for i, suffix in enumerate(suffixes):
        found = False
        for j, group in enumerate(rhyme_groups):
            if group[0] == suffix:
                rhyme_groups[j].append(i + 1)  # 1-indexed line numbers
                found = True
                break
        if not found:
            rhyme_groups.append([suffix, [i + 1]])

    return rhyme_groups

def get_schemes(rhyme_groups):
    """Determine which rhyme schemes fit the quatrain"""
    schemes = []

    # Check if all lines rhyme (aaaa)
    if all(g[1] == [1, 2, 3, 4] for g in rhyme_groups):
        schemes.append('aaaa')

    # Check aabb (lines 1&2 rhyme, 3&4 rhyme)
    if len(rhyme_groups) == 2 and all(g[1] == [1, 2] or g[1] == [3, 4] for g in rhyme_groups):
        schemes.append('aabb')

    # Check abab (lines 1&3 rhyme, 2&4 rhyme)
    if len(rhyme_groups) == 2 and all(g[1] == [1, 3] or g[1] == [2, 4] for g in rhyme_groups):
        schemes.append('abab')

    # Check abba (lines 1&4 rhyme, 2&3 rhyme)
    if len(rhyme_groups) == 2 and all(g[1] == [1, 4] or g[1] == [2, 3] for g in rhyme_groups):
        schemes.append('abba')

    return schemes

def main():
    import sys
    input = sys.stdin.read().splitlines()
    if not input:
        return

    n, k = map(int, input[0].split())
    lines = input[1:4*n + 1]

    # Process each quatrain
    possible_schemes = set(['aabb', 'abab', 'abba', 'aaaa'])

    for i in range(n):
        start_idx = 4 * i
        quatrain_lines = lines[start_idx:start_idx + 4]

        rhyme_groups = get_rhyme_group(quatrain_lines, k)
        if rhyme_groups is None:
            # Some line can't rhyme with any other
            print("NO")
            return

        quatrain_schemes = get_schemes(rhyme_groups)

        # If quatrain fits multiple schemes, we need to choose one
        if quatrain_schemes:
            possible_schemes = possible_schemes.intersection(quatrain_schemes)
        else:
            # Quatrain doesn't fit any scheme
            print("NO")
            return

    if possible_schemes:
        # If there are multiple possible schemes, choose 'aabb' by default
        print("aabb")
    else:
        print("NO")

