def is_valid_word(word):
    # Check if word is a valid Petya's language word
    if word.endswith("lios"):
        return "adjective", "masculine"
    elif word.endswith("liala"):
        return "adjective", "feminine"
    elif word.endswith("etr"):
        return "noun", "masculine"
    elif word.endswith("etra"):
        return "noun", "feminine"
    elif word.endswith("initis"):
        return "verb", "masculine"
    elif word.endswith("inites"):
        return "verb", "feminine"
    else:
        return None, None

words = input().split()

# Check if all words are valid
all_valid = True
parts_of_speech = []
genders = []

for word in words:
    part, gender = is_valid_word(word)
    if part is None or gender is None:
        all_valid = False
        break
    parts_of_speech.append(part)
    genders.append(gender)

if not all_valid:
    print("NO")
elif len(words) == 1:
    # Only one valid word, it's a valid sentence
    print("YES")
else:
    # Check if it's a valid statement
    # Statement format: (adjective)* (noun) (verb)*
    # All words must have the same gender
    gender = genders[0]
    is_valid_statement = True

    # Check gender consistency
    for gender in genders[1:]:
        if gender != genders[0]:
            is_valid_statement = False
            break

    if not is_valid_statement:
        print("NO")
    else:
        # Check order: adjectives, then noun, then verbs
        noun_position = -1
        adjective_count = 0
        verb_count = 0

        for i, part in enumerate(parts_of_speech):
            if part == "adjective":
                adjective_count += 1
            elif part == "noun":
                if noun_position != -1:
                    # Multiple nouns found
                    is_valid_statement = False
                    break
                noun_position = i
            elif part == "verb":
                verb_count += 1

        if is_valid_statement and noun_position != -1:
            # Check order: all adjectives before noun
            for i in range(noun_position):
                if parts_of_speech[i] != "adjective":
                    is_valid_statement = False
                    break

            # Check order: all verbs after noun
            for i in range(noun_position + 1, len(parts_of_speech)):
                if parts_of_speech[i] != "verb":
                    is_valid_statement = False
                    break

