from itertools import permutations

def is_magic_square(mat, n, s):
    # Check rows
    for row in mat:
        if sum(row) != s:
            return False

    # Check columns
    for col in range(n):
        if sum(mat[row][col] for row in range(n)) != s:
            return False

    # Check diagonals
    if mat[0][0] + mat[1][1] + mat[2][2] + mat[3][3] != s:
        return False
    if mat[0][3] + mat[1][2] + mat[2][1] + mat[3][0] != s:
        return False

    return True

def solve_magic_square(n, nums):
    nums.sort()
    used = [False] * len(nums)
    mat = [[0] * n for _ in range(n)]

    def backtrack(pos):
        if pos == len(nums):
            return is_magic_square(mat, n, s)

        # Try placing nums[pos] in each position
        for row in range(n):
            for col in range(n):
                if not used[pos]:
                    mat[row][col] = nums[pos]
                    used[pos] = True

                    # Check if we can continue
                    # Check row sum
                    if sum(mat[row]) == s:
                        if backtrack(pos + 1):
                            return True
                    elif sum(mat[row]) > s:
                        used[pos] = False
                        mat[row][col] = 0
                        continue

                    # Check column sum
                    if sum(mat[row][col] for row in range(n)) == s:
                        if backtrack(pos + 1):
                            return True
                    elif sum(mat[row][col] for row in range(n)) > s:
                        used[pos] = False
                        mat[row][col] = 0
                        continue

                    # Check diagonal sums if we're at the corners
                    if (row == 0 and col == 0) or (row == 0 and col == n-1) or (row == n-1 and col == 0) or (row == n-1 and col == n-1):
                        pass

                    used[pos] = False
                    mat[row][col] = 0
        return False

    total = sum(nums)
    s = total // n

    if backtrack(0):
        return mat
    return None

n = int(input())
nums = list(map(int, input().split()))

# Solve and print solution
mat = solve_magic_square(n, nums)
print(s)
for row in mat:
    print(' '.join(map(str, row)))
