def solve(s, t):
    if len(s) < len(t):
        return -1

    # If length of s > length of t, we can always form a string greater than t
    if len(s) > len(t):
        # Sort s to get the smallest permutation
        s_sorted = sorted(s)

        # Check if the smallest permutation is greater than t
        if s_sorted > t:
            return ''.join(s_sorted)

        # Otherwise, we need to find the lexicographically smallest permutation that is greater
        # We want to match t as much as possible

        # Build the result character by character
        result = []
        used = [False] * len(s)

        def backtrack(pos):
            if pos == len(s):
                result_str = ''.join(result)
                # If we have matched all of t, we need to be strictly greater
                if len(result) > len(t) or (len(result) == len(t) and result_str > t):
                    return result_str
                return None

            for i in range(len(s)):
                if not used[i]:
                    # If we haven't exhausted t, try to match exactly
                    if pos < len(t) and s[i] == t[pos]:
                        result.append(s[i])
                        used[i] = True
                        next_res = backtrack(pos + 1)
                        if next_res is not None:
                            return next_res
                        used[i] = False
                        result.pop()
                    elif pos < len(t) and s[i] > t[pos]:
                        # Use a character that makes it greater
                        result.append(s[i])
                        used[i] = True
                        next_res = backtrack(pos + 1)
                        if next_res is not None:
