def solve():
    n, m = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(input().strip())

    # Find connected components of empty cells
    component_id = [[-1 for _ in range(m)] for _ in range(n)]
    component_size = []
    current_id = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and component_id[i][j] == -1:
                # BFS to find component
                queue = [(i, j)]
                component_id[i][j] = current_id
                component_size.append(1)

                while queue:
                    x, y = queue.pop(0)
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] == '.' and component_id[nx][ny] == -1:
                                component_id[nx][ny] = current_id
                                component_size.append(1)
                                queue.append((nx, ny))
                current_id += 1

    # For each impassable cell, find the size of the component it would join
    result = []
    for i in range(n):
        row = []
        for j in range(m):
            if grid[i][j] == '*':
                # Collect unique component IDs from neighbors
                neighbor_ids = set()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if grid[nx][ny] == '.':
                            neighbor_ids.add(component_id[nx][ny])

                # Sum sizes of distinct components
                total = 1  # for the impassable cell itself
                for cid in neighbor_ids:
                    total += component_size[cid]

                row.append(str(total % 10))
