import sys

def is_lucky_string(s):
    # Group positions by character
    from collections import defaultdict
    pos = defaultdict(list)
    for i, c in enumerate(s, 1):
        pos[c].append(i)

    # Check if string is lucky
    for char in pos:
        positions = pos[char]
        for i in range(1, len(positions)):
            diff = abs(positions[i] - positions[i-1])
            if diff not in {4, 7}:
                return False
    return True

def find_lex_min_lucky_string(n):
    # Greedy approach: try to use smallest possible letters first
    result = []

    for i in range(1, n + 1):
        # Try each letter from 'a' to 'z'
        for c in range(ord('a'), ord('z') + 1):
            candidate = chr(c)

            # Check if this candidate creates an unlucky difference
            # with its previous occurrence
            prev_pos = None
            for j in range(len(result) + 1):
                if j < len(result) and result[j] == candidate:
                    prev_pos = j + 1  # position is 1-indexed
                elif j == len(result):
                    # No previous occurrence, valid
                    break

            if prev_pos is not None:
                diff = abs(i - prev_pos)
                if diff not in {4, 7}:
                    continue

            # Place this character
            result.append(chr(c))
            break

    return ''.join(result)

n = int(sys.stdin.readline())
print(find_lex_min_lucky_string(n))
