                    prev_pos = j + 1  # position is 1-indexed
                elif j == len(result):
                    # No previous occurrence, valid
                    break

            if prev_pos is not None:
                diff = abs(i - prev_pos)
                if diff not in {4, 7}:
                    continue

            # Place this character
            result.append(chr(c))
            break

    return ''.join(result)

