import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    contests = list(map(int, data[1:1+n]))

    contests.sort()

    days = 0
    for k in range(1, n + 1):
        if contests[-1] >= k:
            days += 1
            contests[-1] -= k
        else:
            break

    print(days)

if __name__ == "__main__":
    solve()
