    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    contests = list(map(int, data[1:1+n]))

    contests.sort()
    days = 0
    i = 0

    for k in range(1, n + 1):
        while i < n and contests[i] < k:
            i += 1

        if i < n:
            days += 1
            i += 1
        else:
            break

    print(days)

if __name__ == "__main__":
    solve()

