def solve()
    n = int(input())
    a = list(map(int, input().split()))

    # dp[i][j] = max points for subsequence a[i..j]
    dp = [[0] * n for _ in range(n)]

    # Fill dp table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # If a[i] == a[j], we can remove them together
            if a[i] == a[j]:
                dp[i][j] = dp[i + 1][j - 1] + 1
            else:
                # Otherwise, try removing a[i] or a[j]
                dp[i][j] = max(dp[i + 1][j] + 1, dp[i][j - 1] + 1)

    print(dp[0][n - 1])

solve()
