    for i in range(n):
        dp[i][i] = 1

    # Fill dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # If a[i] == a[j], we can remove them together
            if a[i] == a[j]:
                dp[i][j] = dp[i + 1][j - 1] + 1
            else:
                # Try removing a[i] or a[j] first
                option1 = dp[i + 1][j] + 1
                option2 = dp[i][j - 1] + 1
                option3 = 0

                # Check if there's a k where a[i] == a[k] and try removing them together
                for k in range(i + 1, j + 1):
