def cross(o, a, b):
    """Cross product of vectors a and b from point o"""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def edge_intersection(e1, e2):
    """Find intersection point between edges e1 and e2"""
    # e1 = (p1, p2), e2 = (p3, p4)
    p1, p2 = e1
    p3, p4 = e2

    # Cross products
    c1 = cross(p1, p2, p3)
    c2 = cross(p1, p2, p4)
    c3 = cross(p3, p4, p1)
    c4 = cross(p3, p4, p2)

    # Check if edges intersect
    if (c1 * c2 < 0) and (c3 * c4 < 0):
        # Lines intersect
        # Use parametric form to find intersection
        # Line 1: p1 + t*(p2-p1), Line 2: p3 + s*(p4-p3)
        # Solve: p1 + t*(p2-p1) = p3 + s*(p4-p3)
        # Find t and s
        t_numerator = (p3[0] - p1[0]) * (p4[1] - p3[1]) - (p3[1] - p1[1]) * (p4[0] - p3[0])
        t_denominator = (p2[0] - p1[0]) * (p4[1] - p3[1]) - (p2[1] - p1[1]) * (p4[0] - p3[0])

        if abs(t_denominator) < 1e-9:
            return None  # Collinear

        t = t_numerator / t_denominator
        s = (t_numerator / t_denominator) * (t_denominator / t_numerator)  # Adjusted for better precision

        # Clamp to segment
        if abs(t) > 1e-9:
            if t > 1e-9:
                t = 1.0
            elif t < -1e-9:
                t = 0.0

        if abs(s) > 1e-9:
            if s > 1e-9:
                s = 1.0
            elif s < -1e-9:
                s = 0.0

        # Calculate intersection point
        x = p1[0] + t * (p2[0] - p1[0])
        y = p1[1] + t * (p2[1] - p1[1])
        return (x, y)
    return None


def point_in_rectangle(p, rect):
    """Check if point p is inside rectangle rect"""
    x, y = p
    # Check if point is inside bounding box
    if x < min(rect[0][0], rect[1][0]) - 1e-9 or x > max(rect[0][0], rect[1][0]) + 1e-9:
        return False
    if y < min(rect[0][1], rect[1][1]) - 1e-9 or y > max(rect[0][1], rect[1][1]) + 1e-9:
        return False

    # Check if point is inside all four edges
    def edge(p1, p2, p):
        """Check if point p is on the line segment p1-p2"""
        # Use cross product and dot product
        cross_val = cross(p1, p2, p)
        dot_val = (p[0] - p1[0]) * (p2[0] - p1[0]) + (p[1] - p1[1]) * (p2[1] - p1[1])

        if abs(cross_val) < 1e-9:
            # Collinear
            if 0 <= dot_val <= (p2[0] - p1[0])**2 + (p2[1] - p1[1])**2:
                return True
        return False

    # Check all four edges
    return edge(rect[0], rect[1], p) or edge(rect[1], rect[2], p) or edge(rect[2], rect[3], p) or edge(rect[3], rect[0], p)


def polygon_area(points):
    """Calculate area of polygon using shoelace formula"""
    if len(points) < 3:
        return 0.0

    area = 0.0
    n = len(points)
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i+1)%n]
        area += (x1 * y2 - x2 * y1)
    return abs(area) / 2.0


