n, t = map(int, input().split())

if n == 1:
    if t <= 9:
        print(t)
    else:
        print(-1)
elif n >= 2:
    # Find the smallest n-digit number divisible by t
    # Start with 10^(n-1)
    num = 10 ** (n - 1)
    if num % t == 0:
        print(num)
    else:
        # Add t until we get an n-digit number
        print(num + t)
"}

