words = input().split()

# Define endings and their properties
endings = {
    "lios": ("adjective", "masculine"),
    "liala": ("adjective", "feminine"),
    "etr": ("noun", "masculine"),
    "etra": ("noun", "feminine"),
    "initis": ("verb", "masculine"),
    "inites": ("verb", "feminine")
}

# Check if a word is valid and get its properties
def get_properties(word):
    for ending, (part, gender) in endings.items():
        if word.endswith(ending):
            return part, gender
    return None, None  # invalid word

# Check if all words are valid
all_valid = True
parts = []
all_genders = []
for word in words:
    part, gender = get_properties(word)
    if part is None:
        all_valid = False
        break
    parts.append(part)
    all_genders.append(gender)

if not all_valid:
    print("NO")
else:
    # Check if all words have the same gender
    first_gender = all_genders[0]
    if not all(gender == first_gender for gender in all_genders):
        print("NO")
    else:
        # Check order: adjectives (0+) + noun (1) + verbs (0+)
        # Find the position of the noun
        noun_pos = -1
        for i, part in enumerate(parts):
            if part == "noun":
                noun_pos = i
                break

        if noun_pos == -1:
            # No noun found, can't be a statement
            print("NO")
        else:
            # Check if there are exactly 1 noun
            noun_count = parts.count("noun")
            if noun_count != 1:
                print("NO")
            else:
                # Check adjectives before noun
                if any(part == "adjective" for part in parts[noun_pos + 1:]):
                    print("NO")

                # Check verbs after noun
                if any(part == "verb" for part in parts[:noun_pos]):
                    print("NO")

                # If we've passed all checks, it's valid
                print("YES")
"}

