    n = int(sys.stdin.readline())

    result = []
    for i in range(1, n + 1):
        mod = i % 4
        if mod == 1:
            result.append('a')
        elif mod == 2:
            result.append('b')
        elif mod == 3:
            result.append('c')
        else:  # mod == 0
            result.append('d')

    sys.stdout.write(''.join(result))

if __name__ == "__main__":
    solve()

