def min_time_with_two_oven(n, t, k, d):
    """Calculate minimum time with two ovens using binary search"""
    # Binary search for minimum time
    left = 0
    right = 1000000  # Some large number

    def possible(time):
        """Check if given time is sufficient"""
        # Cakes from first oven: (time // t) * k
        # Cakes from second oven: (max(0, time - d) // t) * k
        return (time // t) * k + (max(0, time - d) // t) * k >= n

    while left < right:
        mid = (left + right) // 2
        if possible(mid):
            right = mid
        else:
            left = mid + 1

    return left

n, t, k, d = map(int, input().split())
one_oven_time = ((n + k - 1) // k) * t
two_oven_time = min_time_with_two_oven(n, t, k, d)

if two_oven_time < one_oven_time:
    print("YES")
else:
    print("NO")
"}

