n, m = map(int, input().split())
names = [input().strip() for _ in range(n)]

# Store incompatible pairs
incompatible = set()
for _ in range(m):
    a, b = input().split()
    incompatible.add((a, b))
    incompatible.add((b, a))

max_size = 0
best_mask = 0

# Try all subsets
for mask in range(1 << n):
    # Check if this subset is valid
    valid = True
    for i in range(n):
        for j in range(i + 1, n):
            if mask & (1 << i) and mask & (1 << j):
                if (names[i], names[j]) in incompatible:
                    valid = False
                    break
        if not valid:
            break

    if valid and bin(mask).count('1') > max_size:
        max_size = bin(mask).count('1')
        best_mask = mask

# Output the result
print(max_size)
for i in range(n):
    if best_mask & (1 << i):
        print(names[i])
"}

