s = input().strip()

# Find all lucky number substrings
lucky_numbers = set()
for i in range(len(s)):
    for j in range(i + 1, len(s) + 1):
        substr = s[i:j]
        if substr[0] == '0' and len(substr) > 1:
            continue  # skip substrings with leading zeroes
        if all(ch in {'4', '7'} for ch in substr):
            lucky_numbers.add(substr)

if not lucky_numbers:
    print(-1)
else:
    # Count frequencies
    freq = {}
    for substr in lucky_numbers:
        freq[substr] = 0
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substr = s[i:j]
            if substr[0] == '0' and len(substr) > 1:
                continue
            if all(ch in {'4', '7'} for ch in substr):
                freq[substr] += 1

    # Find maximum frequency
    max_freq = max(freq.values())

    # Find lexicographically smallest with max frequency
    candidates = [k for k, v in freq.items() if v == max_freq]
    result = min(candidates)

    print(result)
"}

