def solve():
    a, n = map(int, input().split())
    max_val = a + n - 1

    # largest_square_divisor[x] = largest square that divides x
    largest_square_divisor = [1] * (max_val + 1)

    for s in range(2, int(max_val**0.5) + 1):
        s2 = s * s
        for i in range(s2, max_val + 1, s2):
            if s2 > largest_square_divisor[i]:
                largest_square_divisor[i] = s2

    result = 0
    for year in range(a, a + n):
        D = year
        result += D // largest_square_divisor[D]

    print(result)

solve()
"}

