        count = 0
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                if s[i:j] == substr:
                    count += 1
        freq[substr] = count

    # Find maximum frequency
    max_freq = max(freq.values())

    # Find lexicographically smallest substring with max frequency
    result = min([k for k, v in freq.items() if v == max_freq])
    print(result)

