import math

def count_good_pairs(l, r, x, y):
    if y % x != 0:
        return 0

    k = y // x
    count = 0

    # Find all pairs (i, j) such that i*j = k and GCD(i, j) = 1
    # Since i and j are coprime, they must be coprime divisors of k
    for i in range(1, int(k**0.5) + 1):
        if k % i == 0:
            j = k // i
            if math.gcd(i, j) == 1:
                a = x * i
                b = x * j
                if l <= a <= r and l <= b <= r:
                    count += 1
                    # Check if i != j to avoid double counting
                    if i != j:
                        a, b = x * j, x * i
                        if l <= a <= r and l <= b <= r:
                            count += 1

    return count

