import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    l = int(data[0])
    r = int(data[1])
    k = int(data[2])

    result = []
    power = 1  # k^0

    while power <= r:
        if power >= l:
            result.append(power)
        if power > r // k:
            # Prevent overflow: power * k would exceed r
            break
        power *= k

    if not result:
        print("-1")
    else:
        print(" ".join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

