def count_occurrences(s, substr):
    """Count the number of non-overlapping occurrences of substr in s"""
    count = 0
    start = 0
    while True:
        start = s.find(substr, start)
        if start == -1:
            break
        count += 1
        start += len(substr)
    return count

def find_lucky_number(s):
    # Find all lucky substrings
    lucky_substrings = set()
    n = len(s)

    # Generate all substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substr = s[i:j]
            if substr[0] == '0':
                continue  # Skip substrings with leading zeros
            if all(c in {'4', '7'} for c in substr):
                lucky_substrings.add(substr)

    if not lucky_substrings:
        return "-1"

    # Find frequency of each lucky substring
    max_freq = 0
    best_substrings = []

    for substr in lucky_substrings:
        freq = count_occurrences(s, substr)

        if freq > max_freq:
            max_freq = freq
            best_substrings = [substr]
        elif freq == max_freq:
            best_substrings.append(substr)

    # Return lexicographically smallest
    return min(best_substrings)

s = input().strip()
result = find_lucky_number(s)
print(result)
