def get_divisors(n):
    """Return a set of divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

n = int(input())
results = []

for i in range(1, n + 1):
    xi, yi = map(int, input().split())

    if yi == 0:
        # Count all divisors of xi
        divisors = get_divisors(xi)
        results.append(len(divisors))
    else:
        # Check numbers xi - yi to xi - 1
        prev_numbers = set(range(xi - yi, xi))

        # Get divisors of xi
        divisors = get_divisors(xi)

        # Count divisors that do NOT divide any of the previous numbers
        count = 0
        for d in divisors:
            # Check if d divides any previous number
            divides_any = False
            for prev in prev_numbers:
                if prev % d == 0:
                    divides_any = True
                    break
            if not divides_any:
                count += 1
        results.append(count)

# Output all results
for result in results:
    print(result)
