import sys

def is_lucky_string(s):
    """Check if a string is lucky"""
    last_pos = {}

    for i, char in enumerate(s):
        if char in last_pos:
            diff = abs(i + 1 - last_pos[char])  # Positions are 1-indexed
            if diff not in {4, 7}:
                return False
        last_pos[char] = i + 1

    return True

def find_lex_min_lucky_string(n):
    """Find lexicographically minimal lucky string of length n"""
    result = []

    for i in range(n):
        # Try characters from 'a' to 'z'
        for c in range(ord('a'), ord('z') + 1):
            candidate = chr(c)

            # Check if we can place this character at position i+1
            # We need to check all previous positions
            valid = True

            # Check the character we're trying to place
            if candidate in result:
                # Check adjacent positions
                last_index = len(result) - result[::-1].index(candidate)  # Get the last occurrence index
                diff = abs(i + 1 - last_index - 1)  # Convert to 0-indexed
                if diff not in {4, 7}:
                    valid = False

            if valid:
                result.append(candidate)
                break

    return ''.join(result)

if __name__ == "__main__":
    n = int(sys.stdin.readline())
    print(find_lex_min_lucky_string(n))
