    # For each position i, we can move to adjacent positions j where p[j] < p[i] (Qingshan's move)
    # and p[j] > p[i] (Daniel's move)

    # We'll use dynamic programming to determine winning/losing positions
    # Let's build a directed graph where edges represent valid moves

    from collections import defaultdict

    # Build adjacency lists for each position
    graph = defaultdict(list)

    for i in range(1, n + 1):
        # Qingshan's valid moves from i (p[j] < p[i])
        for j in (i - 1, i + 1):
            if 1 <= j <= n and j != i:
                if p[j - 1] < p[i - 1]:
                    graph[i].append(j)

        # Daniel's valid moves from i (p[j] > p[i])
        for j in (i - 1, i + 1):
            if 1 <= j <= n and j != i:
                if p[j - 1] > p[i - 1]:
                    graph[i].append(j)

    # Now we need to determine winning/losing positions
    # Let's use topological sorting to determine if a position is a winning position

    # Invert the graph to determine dependencies
    reverse_graph = defaultdict(list)
    for u in graph:
        for v in graph[u]:
            reverse_graph[v].append(u)

    # Topological sort
    in_degree = {i: 0 for i in range(1, n + 1)}
    for v in graph:
        for u in graph[v]:
            in_degree[u] += 1

    queue = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    # Topological sort
    order = []
    while queue:
        u = queue.pop(0)
        order.append(u)
