def find_lexicographical_min_greater(s: str, t: str) -> str:
    """Find the lexicographically smallest permutation of s that is strictly greater than t."""

    # If s is shorter than t, we can't form a string longer than t, so we just need the smallest permutation of s
    if len(s) < len(t):
        s_sorted = sorted(s)
        if ''.join(s_sorted) > t:
            return ''.join(s_sorted)
        else:
            return '-1'

    # If s has the same length as t, we need the smallest permutation of s that is greater than t
    elif len(s) == len(t):
        s_sorted = sorted(s)
        # Check if any permutation of s is greater than t
        # The smallest permutation of s is already sorted
        if ''.join(s_sorted) > t:
            return ''.join(s_sorted)
        else:
            # Need to find the smallest permutation that is greater than t
            # Try to find the first position where we can swap
            for i in range(len(s_sorted) - 1):
                # We want to find the smallest permutation greater than t
                # Look for the first position where s_sorted[i] < t[i]
                if s_sorted[i] < t[i]:
                    # Find the smallest character greater than t[i]
                    for j in range(i + 1, len(s_sorted)):
                        if s_sorted[j] > t[i]:
                            # Swap them
                            s_sorted[i], s_sorted[j] = s_sorted[j], s_sorted[i]
                            # Sort the rest in increasing order
                            s_sorted[i+1:] = sorted(s_sorted[i+1:])
