def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # The largest disk is at an end
    # Let's try to gather all disks on the opposite end

    max_val = max(a)
    max_index = a.index(max_val)

    # If max is at one end, try to gather all on the other end
    if max_index == 0:
        # Try to gather all on position n-1
        pos = [(i, a[i]) for i in range(n)]

        # Move from left to right
        for i in range(n-1, -1, -1):
            if pos[i][1] == 0:
