def solve():
    n, m, k = map(int, input().split())

    # Generate snake-like sequence
    sequence = []
    for row in range(n):
        if row % 2 == 0:
            # left to right
            for col in range(m):
                sequence.append((row + 1, col + 1))
        else:
            # right to left
            for col in range(m - 1, -1, -1):
                sequence.append((row + 1, col + 1))

    # Split into k tubes
    tube_size = (len(sequence) + k - 1) // k
    tubes = [sequence[i*tube_size : (i+1)*tube_size] for i in range(k)]

    # Output
    for tube in tubes:
        print(len(tube), end=' ')
        for cell in tube:
            print(cell[0], cell[1], end=' ')
        print()

