def max_similarity_score(n, m, A, B):
    # If strings are not too long, we can check all possible substrings
    if n <= 500 and m <= 500:
        max_score = -float('inf')
        for i in range(n):
            for j in range(n - i + 1):
                C = A[i:i+j]
                for k in range(m):
                    for l in range(m - k + 1):
                        D = B[k:k+l]
                        # Calculate LCS
                        lcs = 0
                        # We'll use dynamic programming for LCS
                        dp = [[0] * (l + 1) for _ in range(j + 1)]
                        for x in range(1, j + 1):
                            for y in range(1, l + 1):
                                if C[x-1] == D[y-1]:
                                    dp[x][y] = dp[x-1][y-1] + 1
                                else:
                                    dp[x][y] = max(dp[x-1][y], dp[x][y-1])
                        score = 4 * dp[j][l] - j - l
                        max_score = max(max_score, score)
        return max_score
    else:
        # If strings are long, we can't check all substrings
        # Instead, we can take substrings of length up to 20
        max_k = 20
        max_score = -float('inf')
        for k in range(1, max_k + 1):
            # Try all substrings of length k in A
            for i in range(n - k + 1):
                C = A[i:i+k]
                # Try all substrings of length k in B
                for j in range(m - k + 1):
                    D = B[j:j+k]
                    # Calculate LCS
                    lcs = 0
                    # Use DP for LCS
                    dp = [[0] * (k + 1) for _ in range(k + 1)]
                    for x in range(1, k + 1):
                        for y in range(1, k + 1):
                            if C[x-1] == D[y-1]:
                                dp[x][y] = dp[x-1][y-1] + 1
                            else:
                                dp[x][y] = max(dp[x-1][y], dp[x][y-1])
                    score = 4 * dp[k][k] - k - k
                    max_score = max(max_score, score)
        return max_score

