def is_bipartite(graph, n):
    color = [-1] * n
    for start in range(n):
        if color[start] == -1:
            stack = [(start, 0)]
            color[start] = 0
            while stack:
                node, cur_color = stack.pop()
                for neighbor in graph[node]:
                    if color[neighbor] == -1:
                        color[neighbor] = 1 - cur_color
                        stack.append((neighbor, 1 - cur_color))
                    elif color[neighbor] == cur_color:
                        return False
    return True

