{"code": "
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Read edges
    edges = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        edges[u].append(v)
        edges[v].append(u)
        idx += 2

    # Try all possible colorings
    # Colors: 0='a', 1='b', 2='c'
    # For each vertex, try all 3 colors

    # Check if coloring is valid
    def is_valid(coloring):
        for u in range(1, n + 1):
            for v in edges[u]:
                # u and v should have equal or neighboring colors
                if abs(coloring[u - 1] - coloring[v - 1]) not in {0, 1}:
                    return False
            for v in range(1, n + 1):
                if v == u:
                    continue
                if v not in edges[u]:
                    # u and v should not be neighboring
                    if abs(coloring[u - 1] - coloring[v - 1]) in {0, 1}:
                        return False
        return True

    # Try all colorings
    for color in range(3 ** n):
        coloring = [0] * n
        for i in range(n):
            coloring[i] = color % 3
            color //= 3

        if is_valid(coloring):
            print("Yes")
            print(''.join(chr(ord('a') + c) for c in coloring))
            return

    print("No")

if __name__ == "__main__":
    solve()
