        planet = []
        for _ in range(m):
            a = int(next(it))
            b = int(next(it))
            c = int(next(it))
            planet.append((a, b, c))
        planets.append(planet)

    max_profit = 0

    # Try all pairs of planets (buy, sell)
    for buy_idx in range(n):
        for sell_idx in range(n):
            if buy_idx == sell_idx:
                continue

            # Calculate profit for each item type
            profits = []
            max_buy = []
            for j in range(m):
                a, b, c = planets[buy_idx][j]
                profit = b - a
                if profit > 0:
                    profits.append(profit)
                    max_buy.append(c)
                else:
                    profits.append(0)
                    max_buy.append(0)

            if all(p == 0 for p in profits):
                continue

            # Unbounded knapsack DP
            dp = [0] * (k + 1)
            for j in range(len(profits)):
                p = profits[j]
                cap = max_buy[j]
                for capa in range(k + 1):
                    if capa > cap:
                        continue

                    # Try taking i items of this type
                    for i in range(1, capa + 1):
                        dp[capa] = max(dp[capa], dp[capa - i] + p * i)

            max_profit = max(max_profit, dp[k])

    print(max_profit)

