class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.size = 1
        while self.size < n:
            self.size <<= 1
        self.tree = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)

    def push(self, node, node_left, node_right):
        if self.lazy[node] != 0:
            # Propagate to children
            if node < self.size:
                self.lazy[2*node] += self.lazy[node]
                self.lazy[2*node+1] += self.lazy[node]
                # Update tree values
                self.tree[2*node] += self.lazy[node]
                self.tree[2*node+1] += self.lazy[node]
            self.lazy[node] = 0

    def update_range(self, node, node_left, node_right, l, r, val):
        # Add val to [l, r]
        if node_right < l or node_left > r:
            return

        if l <= node_left and node_right <= r:
            self.tree[node] += val
            self.lazy[node] += val
            return

        self.push(node, node_left, node_right)
        mid = (node_left + node_right) // 2
        self.update_range(2*node, node_left, mid, l, r, val)
        self.update_range(2*node+1, mid+1, node_right, l, r, val)
        self.tree[node] = max(self.tree[2*node], self.tree[2*node+1])

    def query_max(self, node, node_left, node_right, l, r):
        # Query maximum in [l, r]
        if node_right < l or node_left > r:
            return -float('inf')

        if l <= node_left and node_right <= r:
            return self.tree[node]

        self.push(node, node_left, node_right)
        mid = (node_left + node_right) // 2
        left_max = self.query_max(2*node, node_left, mid, l, r)
        right_max = self.query_max(2*node+1, mid+1, node_right, l, r)
        return max(left_max, right_max)

    def query_min(self, node, node_left, node_right, l, r):
        # Query minimum in [l, r]
        if node_right < l or node_left > r:
            return float('inf')

        if l <= node_left and node_right <= r:
            return self.tree[node]

        self.push(node, node_left, node_right)
        mid = (node_left + node_right) // 2
        left_min = self.query_min(2*node, node_left, mid, l, r)
        right_min = self.query_min(2*node+1, mid+1, node_right, l, r)
        return min(left_min, right_min)


def main():
    import sys
    input = sys.stdin.read().split()
    it = iter(input)
    n = int(next(it))
    m = int(next(it))

    tree = SegmentTree(n)

    operations = []
    for _ in range(m):
        t = int(next(it))
        if t == 1:
            l = int(next(it)) - 1
            r = int(next(it)) - 1
            d = int(next(it))
            operations.append((t, l, r, d))
        else:
            l = int(next(it)) - 1
            r = int(next(it)) - 1
            mi = int(next(it))
            operations.append((t, l, r, mi))

    # Process in reverse order
    for op in reversed(operations):
        t, l, r, val = op

        if t == 1:
            # Type 1: Add val to [l, r] (in original order)
            # In reverse, we subtract val from [l, r]
            tree.update_range(1, 0, tree.size-1, l, r, -val)
        else:
            # Type 2: Max in [l, r] is val (in original order)
            # In reverse, we need to ensure max is at least val
            current_max = tree.query_max(1, 0, tree.size-1, l, r)
            current_min = tree.query_min(1, 0, tree.size-1, l, r)

            # If current max is less than needed, we need to increase some values
            if current_max < val:
                # Set minimum value in [l, r] to val
                # Actually, we should set all values in [l, r] to be at least val
                tree.update_range(1, 0, tree.size-1, l, r, val - current_max)

    # Extract array values
    result = []
    for i in range(n):
        result.append(tree.query_max(1, 0, tree.size-1, i, i))

    print("YES")
    print(' '.join(map(str, result)))

