def find_value(x, y):
    """Find the value at position (x, y) in the matrix"""

    if x == y:
        # diagonal d = 2x - 1, value = d(d-1)//2 + x
        d = 2 * x - 1
        return d * (d - 1) // 2 + x
    elif x < y:
        # x < y, d = y, value = d(d-1)//2 + x
        d = y
        return d * (d - 1) // 2 + x
    else:  # x > y
        # x > y, d = x, value = d(d-1)//2 + y
        d = x
        return d * (d - 1) // 2 + y

def solve_query(x1, y1, x2, y2):
    """Calculate the sum of values in rectangle (x1, y1) to (x2, y2)"""
    total = 0

    for x in range(x1, x2 + 1):
        for y in range(y1, y2 + 1):
            total += find_value(x, y)

    # Return the last 10 digits, or the full number if it has <= 10 digits
    if total < 1000000000:
        return str(total)
    else:
        return f"...{total % 1000000000:010d}" 

def main():
    import sys
    input = sys.stdin.read().split()
    if not input:
        return

    t = int(input[0])
    index = 1

    results = []
    for _ in range(t):
        x1 = int(input[index]); index += 1
        y1 = int(input[index]); index += 1
        x2 = int(input[index]); index += 1
        y2 = int(input[index]); index += 1

        result = solve_query(x1, y1, x2, y2)
        results.append(result)

    for result in results:
