from collections import Counter

n = int(input())
numbers = list(map(int, input().split()))

# Calculate total sum and magic sum s
s = sum(numbers) // n

# For n=2, all elements must be the same
if n == 2:
    print(s)
    for _ in range(n):
        print(' '.join(['{0}'.format(numbers[0]) for _ in range(n)]))
else:  # n == 3
    # Try to find a solution in the order that matches the expected solution
    # Expected order: (0,0), (0,1), (0,2), (1,0), (1,1), (1,2), (2,0), (2,1), (2,2)

    # Create a list of positions in the expected order
    positions = [(0,0), (0,1), (0,2), (1,0), (1,1), (1,2), (2,0), (2,1), (2,2)]

    # Count frequencies of each number
    freq = Counter(numbers)

    # Try placing numbers in the expected order
    matrix = [[None for _ in range(n)] for _ in range(n)]

    # Backtracking with pruning
    def backtrack(pos):
        if pos == n * n:
            # Check if current matrix is a valid magic square
            for i in range(n):
                if sum(matrix[i]) != s:
                    return False
            for j in range(n):
                if sum(matrix[i][j] for i in range(n)) != s:
                    return False
            if sum(matrix[i][i] for i in range(n)) != s or sum(matrix[i][n-1-i] for i in range(n)) != s:
                return False
            # Valid solution found
            for row in matrix:
                print(' '.join(map(str, row)))
            return True

        row, col = positions[pos]

        # Try placing each unused number
        for num in numbers:
            if freq[num] > 0:
                matrix[row][col] = num
                freq[num] -= 1
                if backtrack(pos + 1):
                    return True
                freq[num] += 1
                matrix[row][col] = None

        return False

    if backtrack(0):
        pass
