def longest_common_subsequence(s1, s2):
    """Compute LCS of two strings using dynamic programming"""
    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            if s1[i] == s2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    return dp[n][m]

def solve():
    n, m = map(int, input().split())
    A = input().strip()
    B = input().strip()

    max_score = 0

    # Try all possible substring lengths
    for length in range(1, min(n, m) + 1):
        # Try all substrings of A of this length
        for i in range(n - length + 1):
            C = A[i:i + length]
            # Try all substrings of B of this length
            for j in range(m - length + 1):
                D = B[j:j + length]
                # Compute LCS
                lcs = longest_common_subsequence(C, D)
                score = 4 * lcs - length - length

                if score > max_score:
                    max_score = score

    print(max_score)

solve()
