from itertools import permutations

def is_less_or_equal(a, b):
    """Compare strings lexicographically"""
    min_len = min(len(a), len(b))
    for i in range(min_len):
        if a[i] < b[i]:
            return True
        elif a[i] > b[i]:
            return False
    # If we reach here, a is prefix of b or vice versa
    return len(a) <= len(b)

def solve():
    s = input().strip()
    t = input().strip()

    # Check if sorted(s) > t
    sorted_s = ''.join(sorted(s))
    if not is_less_or_equal(sorted_s, t):
        print(sorted_s)
        return

    # Check if sorted_s == t
    if is_less_or_equal(sorted_s, t) and is_less_or_equal(t, sorted_s):
        print(-1)
        return

    # We need to find the smallest permutation > t
    # Try all permutations and return the first one > t

    # For small strings, this works
    seen = set()
    for p in permutations(s):
        seen.add(''.join(p))

    # Sort all permutations lexicographically
    sorted_perms = sorted(seen)

    # Find the first permutation > t
    for perm in sorted_perms:
        if not is_less_or_equal(perm, t):
            print(perm)
            return

    print(-1)

