def solve_magic_square(n, numbers):
    # Calculate the magic constant
    s = sum(numbers) // n

    # Try all permutations
    from itertools import permutations

    # For n=3, 9! = 362,880 permutations is manageable
    for perm in permutations(numbers):
        # Convert to square
        square = [list(perm[i*n:(i+1)*n]) for i in range(n)]

        # Check if it's a magic square
        # Check rows
        valid = all(sum(row) == s for row in square)

        if valid:
            # Check columns
            for j in range(n):
                if sum(square[i][j] for i in range(n)) != s:
                    valid = False
                    break

            if valid:
                # Check main diagonal
                if sum(square[i][i] for i in range(n)) != s:
                    valid = False

                if valid:
                    # Check secondary diagonal
                    if sum(square[i][n-1-i] for i in range(n)) != s:
                        valid = False

                if valid:
                    return square, s

    return None, None

n = int(input())
numbers = list(map(int, input().split()))

square, s = solve_magic_square(n, numbers)
print(s)
for row in square:
    print(' '.join(map(str, row)))
