def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, n = map(int, data)

    # Precompute smallest prime factor (SPF)
    max_d = a + n - 1
    spf = [0] * (max_d + 1)
    for i in range(2, max_d + 1):
        if spf[i] == 0:
            spf[i] = i
            for j in range(i*i, max_d + 1, i):
                if spf[j] == 0:
                    spf[j] = i

    def get_largest_perfect_square_divisor(d):
        # Factorize d using SPF
        factors = {}
        while d > 1:
            p = spf[d]
            while d % p == 0:
                factors[p] = factors.get(p, 0) + 1
                d //= p

        # Compute largest perfect square divisor
        result = 1
        for p, exp in factors.items():
            result *= p ** (2 * (exp // 2))
        return result

    total = 0
    for year in range(a, a + n):
        divisor = get_largest_perfect_square_divisor(year)
        total += year // divisor

    print(total)

if __name__ == "__main__":
    solve()
