def solve():
    n = int(input())
    queries = []
    for _ in range(n):
        xi, yi = map(int, input().split())
        queries.append((xi, yi))

    max_num = 100000
    # Precompute divisors for all numbers up to max_num
    divisor_counts = [set() for _ in range(max_num + 1)]

    for i in range(1, max_num + 1):
        for j in range(i, max_num + 1, i):
            divisor_counts[j].add(i)

    for xi, yi in queries:
        if yi == 0:
            # Count all divisors of xi
            print(len(divisor_counts[xi]))
        else:
            # Count divisors of xi that don't divide any number in [xi - yi, xi - 1]
            divisors = divisor_counts[xi]
            count = 0
            for d in divisors:
                L = xi - yi
                R = xi - 1

                # Check if d divides any number in [L, R]
                # The smallest multiple of d >= L is ceil(L/d) * d
                # The largest multiple of d <= R is floor(R/d) * d
                # If there's overlap, then d divides some number in the range
                smallest_multiple = ((L + d - 1) // d) * d
                if smallest_multiple <= R:
                    # d divides some number in the range
                    continue
                else:
                    count += 1
            print(count)

solve()
