import sys

def get_suffix(line, k):
    """Find the suffix starting from the k-th vowel from the end"""
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Find all vowel indices (0-indexed from the end)
    vowel_indices = []
    for i, char in enumerate(reversed(line)):
        if char in vowels:
            vowel_indices.append(len(line) - i - 1)

    # If there are fewer than k vowels, return None (cannot rhyme)
    if len(vowel_indices) < k:
        return None

    # Find the starting index of the suffix
    start_idx = vowel_indices[k - 1]

    # Return the suffix starting from start_idx
    return line[start_idx:] if start_idx < len(line) else ''

def get_rhyme_pattern(suffixes):
    """Determine which rhyme schemes are possible for a quatrain"""
    if None in suffixes:
        return set()  # No rhyme possible

    # Check all combinations
    schemes = set()

    # aabb: lines 1&2 rhyme, lines 3&4 rhyme
    if suffixes[0] == suffixes[1] and suffixes[2] == suffixes[3]:
        schemes.add('aabb')

    # abab: lines 1&3 rhyme, lines 2&4 rhyme
    if suffixes[0] == suffixes[2] and suffixes[1] == suffixes[3]:
        schemes.add('abab')

    # abba: lines 1&4 rhyme, lines 2&3 rhyme
    if suffixes[0] == suffixes[3] and suffixes[1] == suffixes[2]:
        schemes.add('abba')

    # aaaa: all lines rhyme
    if suffixes[0] == suffixes[1] == suffixes[2] == suffixes[3]:
        schemes.add('aaaa')

    return schemes

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    # First line contains n and k
    parts = data[0].split()
    if len(parts) < 2:
        return
    n = int(parts[0])
    k = int(parts[1])

    # Get suffixes for each line
    suffixes_list = []
    for line in data[1:]:
        suffix = get_suffix(line, k)
        suffixes_list.append(suffix)

    # Process each quatrain
    possible_schemes = set()
    for i in range(n):
        start = i * 4
        quatrain_suffixes = suffixes_list[start:start+4]
        quatrain_schemes = get_rhyme_pattern(quatrain_suffixes)

        # If no scheme possible for this quatrain, whole poem can't be valid
        if not quatrain_schemes:
            print("NO")
            return

        # Intersection with current possible schemes
        possible_schemes.intersection_update(quatrain_schemes)

        # If no schemes left, we can stop early
        if not possible_schemes:
            print("NO")
            return

    # Output the result
    if possible_schemes == {'aaaa'}:
        print("aaaa")
    elif possible_schemes == {'aabb', 'abab', 'abba'}:
        print("NO")
    elif possible_schemes == {'aabb'}:
        print("aabb")
    elif possible_schemes == {'abab'}:
        print("abab")
    elif possible_schemes == {'abba'}:
        print("abba")
    else:
        print("NO")

if __name__ == "__main__":
    main()
"}

