for _ in range(n):
    piece, x, y = input().split()
    x = int(x)
    y = int(y)

    if piece == 'R':
        rooks.append((x, y))
    elif piece == 'B':
        bishops.append((x, y))
    elif piece == 'Q':
        queens.append((x, y))

# Check if king is in check
# For a piece to attack, it must be on the same row, column, or diagonal
# and no other piece can be between them

def can_attack(x1, y1, x2, y2):
    """Check if piece at (x1,y1) can attack king at (x2,y2)"""
    # Check if on same line
    if x1 == x2 or y1 == y2 or abs(x1 - x2) == abs(y1 - y2):
        # Check if there's anything blocking
        blocked = False

        # Sort coordinates
        x_min, x_max = sorted([x1, x2])
        y_min, y_max = sorted([y1, y2])

        # Check if there's any piece between them
        for px, py in rooks + bishops + queens:
            # Check if piece is on the line segment
            if (x_min <= px <= x_max and y_min <= py <= y_max):
                # Check if piece is on the same line
                if x1 == x2 and px != x1:
                    continue  # Same column, skip checking
                if y1 == y2 and py != y1:
                    continue  # Same row, skip checking
                if abs(x1 - x2) == abs(y1 - y2) and (px != x1 and py != y1):
                    continue  # Same diagonal, skip checking

                # Check if piece is between them
                if (y1 != y2 and y_min <= py <= y_max and (px - x_min) * (x2 - x1) == (py - y1) * (y2 - y1)):
                    blocked = True
                    break

        return not blocked
    return False

# Check all pieces
for x, y in rooks:
    if can_attack(x, y, x0, y0):
        print("YES")
        exit()

for x, y in bishops:
    if can_attack(x, y, x0, y0):
        print("YES")
        exit()

for x, y in queens:
    if can_attack(x, y, x0, y0):
        print("YES")
        exit()

print("NO")
