current = 1  # k^0

while True:
    if current > r:
        break
    if current >= l:
        result.append(current)
    # Check if multiplying by k would exceed r to avoid infinite loop
    if current > r // k:
        break
    current *= k

if not result:
    print(-1)
else:
    print(' '.join(map(str, result)))

