def check_win(board, i, j):
    # Check all 8 directions
    directions = [(0, 1), (1, 0), (1, 1), (1, -1)]

    for di, dj in directions:
        count = 1
        ni, nj = i + di, j + dj

        # Extend in the direction
        while 0 <= ni < 10 and 0 <= nj < 10 and board[ni][nj] == 'X':
            count += 1
            ni += di
            nj += dj

        # Extend in the opposite direction
        ni, nj = i - di, j - dj
        while 0 <= ni < 10 and 0 <= nj < 10 and board[ni][nj] == 'X':
            count += 1
            ni -= di
            nj -= dj

        if count >= 5:
            return True

    return False

def solve():
    board = []
    for _ in range(10):
        line = input().strip()
        board.append(list(line))

    for i in range(10):
        for j in range(10):
