import sys

def sum_of_digits(x):
    """Return the sum of digits of x"""
    return sum(int(d) for d in str(x))

def solve():
    n = int(sys.stdin.readline())

    # Find the number of digits in n
    digits = len(str(n))

    # Iterate through possible x values
    valid_x = []
    for x in range(max(1, n - 9 * digits), n):
        if x + sum_of_digits(x) == n:
            valid_x.append(x)

    # Output the results
    print(len(valid_x))
    for x in valid_x:
        print(x)

if __name__ == "__main__":
    solve()
"}

